#!/usr/bin/env bash
# Mutation proof for honey-heartbeat (generated by agents-bots-honey.org): each sabotaged copy MUST fail test_honey_heartbeat.py by a NAMED failure.
# Exit 0 = every mutant killed, 1 = a survivor or an error. The real program is not modified.
set -uo pipefail
HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
PROG="${HONEY_HEARTBEAT:-}"
[ -n "$PROG" ] || for c in "$HERE/../../../bin/honey-heartbeat" "$HERE/honey-heartbeat"; do [ -f "$c" ] && { PROG="$c"; break; }; done
[ -f "$PROG" ] || { echo "mutation-check-heartbeat: program not found"; exit 1; }
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fail=0; killed=0
mutate() { # name sed-expression
  local name="$1" expr="$2" d="$TMP/$1" out rc names
  mkdir -p "$d"; cp "$PROG" "$d/honey-heartbeat"; sed -i "$expr" "$d/honey-heartbeat"
  if cmp -s "$PROG" "$d/honey-heartbeat"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  out="$(HONEY_HEARTBEAT="$d/honey-heartbeat" timeout 300 python3 "$HERE/test_honey_heartbeat.py" 2>&1)"; rc=$?
  if [ "$rc" = 124 ] || ! printf '%s\n' "$out" | grep -qE '^(FAILED \(|OK)'; then echo "INFRASTRUCTURE ERROR (not a kill): $name"; printf '%s\n' "$out" | tail -4 | sed 's/^/    | /'; fail=1; return; fi
  names="$(printf '%s\n' "$out" | grep -E '^(FAIL|ERROR):' | sed 's/^[A-Z]*: //; s/ (.*//' | head -3 | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name by: $names"; else echo "SURVIVED (tests too weak): $name"; fail=1; fi
}
mutate dead-reported-as-silent        "s/            out\['state'\] = 'DEAD'\$/            out['state'] = 'NO-HEARTBEAT'/"
mutate silent-reported-as-dead        "s/out\['state'\], out\['reason'\] = 'NO-HEARTBEAT', 'process alive but %s' % problem/out['state'], out['reason'] = 'DEAD', 'x'/"
mutate stale-beat-ignored             "s/    elif age > max_age:/    elif False:/"
mutate pid-mismatch-ignored           "s/    elif rec\['pid'\] != pid:/    elif False:/"
mutate unhealthy-ignored              "s/    elif rec.get('status') != 'ok':/    elif False:/"
mutate future-beat-accepted           "s/    elif age < -60:/    elif False:/"
mutate zombie-counts-as-alive         "s/state in ('Z', 'X')/state in ('X',)/"
mutate unknown-merged-into-dead       "s/        if proc == 'no-pidfile' and rec is None and problem == 'no heartbeat file':/        if False:/"
mutate exit-codes-collapsed           "s/'NO-HEARTBEAT': 2, 'DEAD': 3/'NO-HEARTBEAT': 2, 'DEAD': 2/"
mutate unhealthy-shares-silent-code   "s/'UNHEALTHY': 1/'UNHEALTHY': 2/"
mutate seq-never-increments           "s/'seq': seq + 1/'seq': 1/"
mutate name-not-validated             "s/    if not NAME_RE.match(name):/    if False:/"
mutate status-not-validated           "s/    if status not in ('ok', 'degraded', 'failing'):/    if False:/"
mutate check-all-exits-with-last      "s/worst = max(worst, r\['exit'\])/worst = r['exit']/"
mutate beat-pid-not-parent            "s/int(opts.get('pid', os.getppid()))/int(opts.get('pid', os.getpid()))/"
mutate usage-error-looks-like-state   "s/        return 64\$/        return 4/"
mutate detail-not-truncated           "s/str(detail)\[:200\]/str(detail)/"
mutate network-import-added           "s/^import json, os, re, sys, time\$/import json, os, re, sys, time, socket/"
mutate shells-out-to-alert            "s/^STATES = /import subprocess\nSTATES = /"
mutate dead-reason-drops-last-beat    "s/('; last heartbeat %.0fs ago' % age if age is not None else '; no heartbeat ever recorded')/'; no heartbeat ever recorded'/"
mutate boundary-off-by-one            "s/    elif age > max_age:/    elif age >= max_age:/"
mutate dead-beat-rescues-process      "s/    if proc != 'alive':/    if proc != 'alive' and rec is None:/"
echo "mutants: $killed killed"
[ "$fail" = 0 ] || exit 1
exit 0
